/**
 * The arms on the title screen's wall.
 *
 * Scenery, not gear: nothing equips these, so they sit apart from GEAR_ART and
 * carry their own palette — one with real timber in it, which the gear palettes
 * do not have because no piece of armour is made of wood. Generated by
 * tools/wall_arms.py; edit there, not here.
 *
 * All of them are cut to one 16x32 frame and hang point-down, so a rack lines
 * any set of them up on a single beam without a per-item nudge.
 */

/** Steel and timber are fixed; only the accent changes from rack to rack. */
export function armsPalette(accent, lit) {
  return {
    o: '#0b0a10',
    s: '#2b323d',
    m: '#6b7686',
    l: '#dce5f2',
    W: '#7a5230',
    w: '#492e19',
    A: accent,
    E: lit ?? accent,
  }
}

