/** One arm + one accent = one sprite, built on demand. */
export function armSprite(kind, accent, lit) {
  const grid = ARMS[kind] ?? ARMS.sword
  return { w: grid[0].length, h: grid.length, palette: armsPalette(accent, lit), grid }
}
